"""Build the print-ready developer guide using Python's standard library."""
from pathlib import Path
from html import escape as E
from base64 import b64encode

OUT = Path(__file__).parent
pages = []
def p(s): return '<p>'+s+'</p>'
def note(s): return '<aside>'+s+'</aside>'
def table(headers, rows):
    return '<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table>'
def diagram(labels, caption, vertical=False):
    n=len(labels); w=720; h=n*64+10 if vertical else 128
    svg=f'<svg viewBox="0 0 {w} {h}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="{E(caption)}"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3 z" fill="#218887"/></marker></defs>'
    for i,label in enumerate(labels):
        x,y,bw,bh=(100,i*64+5,520,48) if vertical else (i*w/n+3,18,w/n-24,75)
        if i:
            x1,y1,x2,y2=(360,y-16,360,y-1) if vertical else (x-24,55,x-3,55)
            svg+=f'<path d="M{x1},{y1} L{x2},{y2}" stroke="#218887" stroke-width="2" marker-end="url(#arrow)"/>'
        svg+=f'<rect x="{x}" y="{y}" width="{bw}" height="{bh}" rx="8" fill="{["#e3f1f1","#e8edf8","#fff0db"][i%3]}" stroke="#b7cbd5"/>'
        parts=label.split('|')
        for j,line in enumerate(parts):
            svg+=f'<text x="{x+bw/2}" y="{y+bh/2+(j-(len(parts)-1)/2)*17+5}" text-anchor="middle" font-family="Arial" font-size="14" fill="#15354c">{E(line)}</text>'
    return svg+'</svg><figcaption>'+caption+'</figcaption>'
def page(title, subtitle, body): pages.append((title,subtitle,body))
def features(title, subtitle, rows, figure=None):
    body=diagram(*figure) if figure else ''
    for name,stack,behavior,examples,limit in rows:
        body+=f'<article><h3>{name}</h3><p><b>Software:</b> {stack}</p><p>{behavior}</p><div class="examples"><b>Real-life uses</b><ul>'+''.join('<li>'+s+'</li>' for s in examples)+'</ul></div><p class="limit"><b>Conditions:</b> '+limit+'</p></article>'
    page(title,subtitle,body)

